42	     * resetting here would pull it out from under the tests running alongside.
43	     */
44	    if (testInfo.tags.some(tag => PARALLEL_TAG_PATTERN.test(tag))) {
45	      await provide();
46	
47	      return;
48	    }
49	
50	    const dumpPath = await ensureScenario(config, scenario);
51	
52	    restoreScenario(config, dumpPath);
53	
54	    await provide();
55	  },
56	
57	  storageState: async ({ actor, seed }, provide) => {
58	    void seed;
59	
60	    if (actor === "anonymous") {
61	      await provide(undefined);
62	
63	      return;
64	    }
65	
66	    await provide(storageStatePath(config, actor));
67	  },
68	});
