async (page) => {
  await page.getByTestId('discount-section-toggle').click();
  await page.waitForTimeout(800);
  const expanded = await page.getByTestId('OrderSummary').innerText();
  const ids = await page.getByTestId('OrderSummary').locator('[data-test-id]').evaluateAll(els => els.map(e => e.tagName + ':' + e.getAttribute('data-test-id') + '=' + e.textContent.slice(0,80)));
