210	const createPromotions = async (mutate: Mutate, shop: Shop, teeProductId: string) => {
211	  if (shop.promotionIds.length > 0) {
212	    await mutate(
213	      "promotionBulkDelete",
214	      `mutation($ids: [ID!]!) { promotionBulkDelete(ids: $ids) { errors { field code message } } }`,
215	      { ids: shop.promotionIds },
216	    );
217	  }
218	
219	  const create = (input: Record<string, unknown>) =>
220	    mutate(
221	      "promotionCreate",
222	      `mutation($input: PromotionCreateInput!) {
223	        promotionCreate(input: $input) { errors { field code message } }
224	      }`,
225	      { input },
226	    );
227	
228	  await create({
229	    name: PROMOTIONS.catalogue.name,
230	    type: "CATALOGUE",
231	    rules: [
232	      {
233	        channels: [shop.channelId],
234	        rewardValueType: "PERCENTAGE",
235	        rewardValue: PROMOTIONS.catalogue.percent,
236	        cataloguePredicate: { productPredicate: { ids: [teeProductId] } },
237	      },
238	    ],
239	  });
240	  await create({
241	    name: PROMOTIONS.order.name,
242	    type: "ORDER",
243	    rules: [
244	      {
245	        channels: [shop.channelId],
246	        rewardType: "SUBTOTAL_DISCOUNT",
247	        rewardValueType: "PERCENTAGE",
248	        rewardValue: PROMOTIONS.order.percent,
249	        orderPredicate: {
250	          discountedObjectPredicate: {
251	            baseSubtotalPrice: { range: { gte: PROMOTIONS.order.subtotalAtLeast } },
252	          },
253	        },
254	      },
255	    ],
256	  });
257	};
